1	import type { MetadataRoute } from "next";
2	
3	const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
4	
5	export default function robots(): MetadataRoute.Robots {
6	  return {
7	    rules: [
8	      {
9	        userAgent: "*",
10	        allow: "/",
11	        // Note: /riddle/chamber-of-echoes is GATE 2 of the Nxeon Cipher promo — the one
12	        // disallowed path that isn't infra. Seekers who "read what the crawlers must
13	        // not" find the hidden chamber here.
14	        disallow: ["/dashboard", "/admin", "/api", "/login", "/register", "/forgot-password", "/reset-password", "/riddle/chamber-of-echoes"],
15	      },
16	    ],
17	    sitemap: `${APP_URL}/sitemap.xml`,
18	    host: APP_URL,
19	  };
20	}
