479	/**
480	 * The real, authoritative download for a mod detail page. Prefers the
481	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
482	 * install it) so a visitor gets the actual file, not just a landing page;
483	 * falls back to the mod's own project/resource page (still the real,
484	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
485	 * be resolved live or isn't one of the three we know how to resolve.
486	 */
487	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
488	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
489	  const id = mod.sourceId ?? "";
490	  if (!id) return fallback;
491	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
492	  try {
493	    if (mod.source === "modrinth") {
494	      const headers: Record<string, string> = { "User-Agent": UA };
495	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
496	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
497	      if (!res.ok) return fallback;
498	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
499	      const v = versions[0];
500	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
501	      return file ? { url: file.url, direct: true } : fallback;
502	    }
503	    if (mod.source === "spigotmc") {
504	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
505	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
506	    }
507	    if (mod.source === "thunderstore") {
508	      const [namespace, ...rest] = id.split("-");
509	      if (!namespace || !rest.length) return fallback;
510	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
511	        headers: { "User-Agent": UA },
512	        next: { revalidate: 3600 },
513	      });
514	      if (!res.ok) return fallback;
515	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
516	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
517	    }
518	  } catch {
519	    return fallback;
520	  }
521	  return fallback;
522	}
