526	  spigotmc: "SpigotMC",
527	  hangar: "Hangar",
528	  curseforge: "CurseForge",
529	  steam_workshop: "Steam Workshop",
530	  umod: "uMod",
531	  github: "GitHub",
532	  nexus: "Nexus Mods",
533	  thunderstore: "Thunderstore",
534	  codefling: "Codefling",
535	  mod_io: "mod.io",
536	};
537

  /// metadata has no equivalent longer field to fetch (its `description` IS
  /// the whole of what GitHub offers for a one-liner — see
  /// scripts/backfill-modrinth-descriptions.ts's file header for the
  /// per-source investigation). Null for every mod this hasn't been
  /// backfilled for yet, or whose source has nothing longer to offer —
  /// never a guess or a copy of `description`.
  longDescription String?   @db.Text

  /// The mod's REAL last-modified timestamp on its OWN upstream source —
  /// never derived from this row's own `updatedAt` above, which only marks
  /// when WE last touched the row (a bulk re-import, a verify pass) and says
  /// nothing about when the mod's actual author last shipped anything. Null
  /// until backfilled/verified against the source. Populated by
  /// scripts/backfill-upstream-updated.ts from the real, confirmed-live field
  /// per source: Modrinth's project `updated` (its bulk `/v2/projects?ids=`
  /// response — NOT `date_modified`, which doesn't exist on the real API),
  /// GitHub's repo `pushed_at`, Thunderstore's latest-version `date_created`
