/**
 * Sitemap-chunking helpers for the NxLabs mod catalogue (app/sitemap.ts +
 * app/sitemap.xml/route.ts).
 *
 * Google's sitemap protocol hard-caps a single sitemap file at 50,000 URLs
 * (and 50MB uncompressed) — see
 * https://www.sitemaps.org/protocol.html#index. The NxLabs catalogue alone
 * is 45,761 mod URLs as of 2026-09-20 (lib/mods-catalog.ts's
 * `listCatalogSlugs()` filter: active + upstreamOk) and growing with every
 * import batch, so a single flat sitemap combining it with the ~1,460 other
 * marketing routes was already effectively at the ceiling and would breach
 * it outright on the next import. This file is the shared math + query
 * layer behind splitting the mod URLs into fixed-size chunks, each served
 * as its own sitemap file, discoverable through a real `<sitemapindex>` at
 * /sitemap.xml (app/sitemap.xml/route.ts) — see that file's header for why
 * a hand-written index route exists alongside app/sitemap.ts's
 * `generateSitemaps()` rather than relying on Next to build one
 * automatically (it doesn't: with `generateSitemaps()` present, Next
 * replaces the flat /sitemap.xml route entirely with /sitemap/[id].xml, per
 * https://nextjs.org/docs/app/api-reference/file-conventions/metadata/sitemap#generating-multiple-sitemaps
 * — "Your generated sitemaps will be available at /.../sitemap/[id].xml.").
 */
import { db } from "@/lib/db";

/**
 * URLs per mod sitemap chunk. 15,000 leaves ~70% headroom under Google's
 * 50,000 ceiling (not cutting it close) while keeping the chunk count from
 * growing too fast as the catalogue expands — at 45,761 mods today that's 4
 * chunks; it stays comfortably chunked well past 200,000 mods before
 * needing a smaller size or a second axis to split on.
 */
export const MOD_SITEMAP_CHUNK_SIZE = 15_000;

/**
 * Real count of publicly-indexable mods — the exact same `active &&
 * upstreamOk` filter `listCatalogSlugs()` (lib/mods-catalog.ts) and the
 * catalogue pages themselves apply, so the sitemap never claims to index a
 * "no longer supported" mod. Defensive try/catch matches this codebase's
 * existing convention in app/sitemap.ts for tables that might not be
 * migrated yet in every environment.
 */
export async function countIndexableMods(): Promise<number> {
  try {
    return await db.gameMod.count({ where: { active: true, upstreamOk: true } });
  } catch {
    return 0;
  }
}

/** How many chunk sitemaps `countIndexableMods()`'s result needs, at `MOD_SITEMAP_CHUNK_SIZE` URLs each. */
export function modChunkCountFor(modCount: number): number {
  return modCount > 0 ? Math.ceil(modCount / MOD_SITEMAP_CHUNK_SIZE) : 0;
}

/**
 * One deterministic page of {family, slug} pairs. `orderBy: { id: "asc" }`
 * is load-bearing, not decorative: each /sitemap/[id].xml chunk is fetched
 * as its own independent request (possibly seconds or minutes apart, by a
 * crawler working through the index), so `skip`/`take` only partitions the
 * real table into complete, non-overlapping chunks if every request sees
 * the same stable ordering — an unordered `findMany` has no such guarantee.
 */
export async function listIndexableModSlugsChunk(chunkIndex: number): Promise<{ family: string; slug: string }[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true },
    select: { gameFamily: true, slug: true },
    orderBy: { id: "asc" },
    skip: chunkIndex * MOD_SITEMAP_CHUNK_SIZE,
    take: MOD_SITEMAP_CHUNK_SIZE,
  });
  return rows.map((r) => ({ family: r.gameFamily, slug: r.slug }));
}

