import { NextResponse } from "next/server";
import { countIndexableMods, modChunkCountFor } from "@/lib/sitemap-mods";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

/**
 * The REAL sitemap index at /sitemap.xml.
 *
 * This is a hand-written Route Handler, not the `sitemap.ts` special-file
 * convention — a deliberate choice, not an oversight. Next.js's
 * `generateSitemaps()` API (used by app/sitemap.ts for the actual URL
 * chunks below) does NOT build a combined index automatically: per the
 * Next.js docs (Generating multiple sitemaps —
 * https://nextjs.org/docs/app/api-reference/file-conventions/metadata/sitemap#generating-multiple-sitemaps),
 * "Your generated sitemaps will be available at /.../sitemap/[id].xml" —
 * full stop. Confirmed against this project's installed next@15.5.21: once
 * a `sitemap.ts` file exports `generateSitemaps()`, Next replaces the flat
 * `/sitemap.xml` route entirely with `/sitemap/[id].xml` — there is no
 * automatic `<sitemapindex>` anywhere. Without this file, nothing would
 * exist at `/sitemap.xml` at all (a real 404), and nothing would tell a
 * crawler how many chunk ids exist or where to find them.
 *
 * `countIndexableMods()`/`modChunkCountFor()` are the exact same functions
 * app/sitemap.ts's own `generateSitemaps()` uses to decide how many mod
 * chunks to produce — imported from the one shared module
 * (lib/sitemap-mods.ts) specifically so this index can never drift out of
 * sync with the real chunk ids app/sitemap.ts actually serves.
 */
export async function GET() {
  const modCount = await countIndexableMods();
  const modChunks = modChunkCountFor(modCount);
  const now = new Date().toISOString();

  // ids 0..modChunks — id 0 is the static/marketing sitemap, ids 1..modChunks
  // are the mod URL chunks. Must match app/sitemap.ts's generateSitemaps()
  // exactly (same shared helpers, so it does).
  const sitemapUrls = Array.from({ length: modChunks + 1 }, (_, i) => `${APP_URL}/sitemap/${i}.xml`);

  const body = `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapUrls
    .map((url) => `  <sitemap>\n    <loc>${url}</loc>\n    <lastmod>${now}</lastmod>\n  </sitemap>`)
    .join("\n")}\n</sitemapindex>\n`;

  return new NextResponse(body, {
    headers: {
      "Content-Type": "application/xml",
      "Cache-Control": "public, max-age=0, must-revalidate",
    },
  });
}

