export const dynamic = "force-dynamic";

type Params = { params: Promise<{ family: string; slug: string }> };

export async function generateStaticParams(): Promise<Array<{ family: string; slug: string }>> {
  return listCatalogSlugs();
}

/**
 * Real, non-fabricated images for a mod, in preference order: its own icon
 * first (the small square logo every card/detail page already leads with),
 * then its real gallery screenshots (Modrinth's project `gallery[]`).
 * Returns [] for a mod with neither — callers must omit the `image`/`images`
 * property entirely rather than pad it with a stand-in, matching this
 * catalogue's no-guessing convention (see lib/mods-catalog.ts's file header).
 */
function realImagesFor(mod: Pick<ModDetail, "iconUrl" | "galleryUrls">): string[] {
  return [mod.iconUrl, ...mod.galleryUrls].filter((url): url is string => !!url);
}

/**
 * A proper ~150-160 char meta description, preferring the real
 * `longDescription` (Modrinth's own project body, backfilled by
 * scripts/backfill-modrinth-descriptions.ts) over the short `description`
 * tagline when it's available — the short tagline is often thin, one line,
 * or (pre-backfill) literally missing, while the source's own longer body is
 * real prose that reads better truncated to meta-description length. Falls
 * back to `description`, then to a description built entirely from other
 * real fields (name/family/source) — never fabricated copy.
 */
function metaDescriptionFor(mod: Pick<ModDetail, "name" | "gameFamilyLabel" | "source" | "description" | "longDescription">): string {
  const raw = mod.longDescription?.trim() || mod.description?.trim() || "";
  if (raw) {
    // longDescription is raw Markdown — strip the common markup so a meta
    // tag doesn't read "## Features\n- ..." verbatim, then collapse
    // whitespace/newlines into a single line before truncating.
    const plain = raw
      .replace(/```[\s\S]*?```/g, " ")
      .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/[#>*_`~-]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (plain.length <= 160) return plain;
    const cut = plain.slice(0, 157);
    const lastSpace = cut.lastIndexOf(" ");
    return `${cut.slice(0, lastSpace > 100 ? lastSpace : 157)}…`;
  }
  return `${mod.name} for ${mod.gameFamilyLabel}, verified against ${SOURCE_LABEL[mod.source] ?? mod.source} — real download counts, supported versions, and a direct download link.`;
}

export async function generateMetadata({ params }: Params): Promise<Metadata> {
  const { family, slug } = await params;
  const mod = await getCatalogMod(family, slug);
  if (!mod) return { title: "Mod not found" };
  const title = `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`;
  const description = metaDescriptionFor(mod);
  const images = realImagesFor(mod);
  const canonicalUrl = `${APP_URL}/mods/${mod.gameFamily}/${mod.slug}`;
  return {
    title,
    description,
    // The only other place this mod's detail is ever rendered is the portal
    // at /dashboard/nxlabs/[family]/[slug] — entirely disallowed in
    // app/robots.ts (`disallow: ["/dashboard", ...]`), so it's not crawlable
    // and can't compete with this page as duplicate content. This canonical
    // still costs nothing to keep as a defensive, standard tag.
    alternates: { canonical: canonicalUrl },
    openGraph: {
      title,
      description,
      type: "website",
      url: canonicalUrl,
      ...(images.length > 0 ? { images } : {}),
    },
    twitter: {
      card: images.length > 0 ? "summary_large_image" : "summary",
      title,
      description,
      ...(images.length > 0 ? { images } : {}),
    },
  };
}

