57	 * tagline when it's available — the short tagline is often thin, one line,
58	 * or (pre-backfill) literally missing, while the source's own longer body is
59	 * real prose that reads better truncated to meta-description length. Falls
60	 * back to `description`, then to a description built entirely from other
61	 * real fields (name/family/source) — never fabricated copy.
62	 */
63	function metaDescriptionFor(mod: Pick<ModDetail, "name" | "gameFamilyLabel" | "source" | "description" | "longDescription">): string {
64	  const raw = mod.longDescription?.trim() || mod.description?.trim() || "";
