69	    const plain = raw
70	      .replace(/```[\s\S]*?```/g, " ")
71	      .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
72	      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
73	      .replace(/[#>*_`~-]/g, " ")
74	      .replace(/\s+/g, " ")
